+/// Still frames as the shell runs them: a frame, then a scene collect.
+fn still_frames(h: &mut Harness<'static, ShellUi>, n: usize) {
+    for _ in 0..n {
+        h.step();
+        std::hint::black_box(world::collect(&h.state().state));
+    }
+}
